package com.earthtrip.notification.adapter.in.web.api.v1.me.notifications.by_notification_id.read_receipt;import com.earthtrip.notification.application.port.in.NotificationUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/me/notifications/{notificationId}/read-receipt") class NotificationReadReceiptController{private final NotificationUseCase useCase;private final CurrentActor actor;NotificationReadReceiptController(NotificationUseCase u,CurrentActor a){useCase=u;actor=a;}@PutMapping @ResponseStatus(HttpStatus.NO_CONTENT)void put(@PathVariable UUID notificationId){useCase.markRead(actor.requireUserId(),notificationId,true);}@DeleteMapping @ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID notificationId){useCase.markRead(actor.requireUserId(),notificationId,false);}}
